Here is the commit message:
sd-netlink: fix rtnl_resolve_link_alternative_name()

Fixes a bug introduced by afdf6c3b6040ef43b05428b834f0f302c8ce9a1b.

Here is the root cause:
The bug was caused by using the incorrect variable `message` instead of `reply` when reading the interface name in the `rtnl_resolve_link_alternative_name` function. This led to incorrect data being processed, resulting in failures to resolve the alternative link names correctly.

Here is the patch:

 int rtnl_resolve_link_alternative_name(sd_netlink **rtnl, const char *name, char **ret) {
         _cleanup_(sd_netlink_unrefp) sd_netlink *our_rtnl = NULL;
         _cleanup_(sd_netlink_message_unrefp) sd_netlink_message *message = NULL, *reply = NULL;
         int r, ifindex;

         assert(name);

         /* This returns ifindex and the main interface name. */

         if (!ifname_valid_full(name, IFNAME_VALID_ALTERNATIVE))
                 return -EINVAL;

         if (!rtnl)
                 rtnl = &our_rtnl;
         if (!*rtnl) {
                 r = sd_netlink_open(rtnl);
                 if (r < 0)
                         return r;
         }

         r = sd_rtnl_message_new_link(*rtnl, &message, RTM_GETLINK, 0);
         if (r < 0)
                 return r;

         r = sd_netlink_message_append_string(message, IFLA_ALT_IFNAME, name);
         if (r < 0)
                 return r;

         r = sd_netlink_call(*rtnl, message, 0, &reply);
         if (r == -EINVAL)
                 return -ENODEV; /* The device doesn't exist */
         if (r < 0)
                 return r;

         r = sd_rtnl_message_link_get_ifindex(reply, &ifindex);
         if (r < 0)
                 return r;
         assert(ifindex > 0);

         if (ret) {
-                r = sd_netlink_message_read_string_strdup(message, IFLA_IFNAME, ret);
+                r = sd_netlink_message_read_string_strdup(reply, IFLA_IFNAME, ret);
                 if (r < 0)
                         return r;
         }

         return ifindex;
 }



